	public static SceneHandle SolveSceneHandleDrag(SceneHandle start, GizmoMode mode, in EditorGizmoOpsDragState drag, in EditorGizmoOpsDragValue valueValue, Quat gizmoOrientation, in EditorGizmoOpsSnapSettings snap) {
		if (Bridge.OffMainThread) {
			Bridge.ThrowOffMainThread("EditorGizmoOps.SolveSceneHandleDrag");
		}
		ArgumentNullException.ThrowIfNull(start);
		EditorGizmoOpsDragState dragCopy = drag;
		EditorGizmoOpsDragValue valueValueCopy = valueValue;
		EditorGizmoOpsSnapSettings snapCopy = snap;
		ulong* slots = stackalloc ulong[8];
		slots[0] = start.Pointer;
		slots[1] = (ulong)(long)(int)mode;
		slots[2] = (ulong)&dragCopy;
		slots[3] = (ulong)&valueValueCopy;
		SlotValues.Put(slots + 4, gizmoOrientation);
		slots[6] = (ulong)&snapCopy;
		int status = EditorBindings.table.editorGizmoOpsSolveSceneHandleDrag(slots, slots + 7);
		if (status != Bridge.OK) {
			throw Bridge.Failure(status, "EditorGizmoOps.SolveSceneHandleDrag");
		}
		return NativeObject.Wrap(slots[7], true, static (pointer, owned) => new SceneHandle(pointer, owned), null)!;
	}

